sys_script_fix.script:
var incidentSysId = 'a0cce22444aa7010f877c1d6e11bbdf5';
var solutionName = 'ml_x_ctsi_sn_itsm_gen_ai_global_synergize_similarity_defintiion';

var incidentGR = new GlideRecord('incident');
var similarityIncidentsNumber = [];
var similarityIncidentsID= [];
var similarityIncidentsResolutionCode = [];

if (!incidentGR.get(incidentSysId)) {
    gs.error(
        'SIMILARITY TEST: Incident not found: ' +
        incidentSysId
    );
} else {
    try {
        var mlSolution =
            sn_ml.MLSolutionFactory.getSolution(
                solutionName
            );

        var input = [{
            short_description: incidentGR.getValue(
                'short_description'
            ) || '',

            description: incidentGR.getValue(
                'description'
            ) || '',

            category: incidentGR.getValue(
                'category'
            ) || '',

            subcategory: incidentGR.getValue(
                'subcategory'
            ) || '',

            cmdb_ci: incidentGR.getValue(
                'cmdb_ci'
            ) || ''
        }];

        var options = {
            top_n: 5
        };

        var rawResults =
            mlSolution.predict(
                input,
                options
            );

        gs.info(
            'SIMILARITY TEST: Raw prediction = ' +
            rawResults
        );

        var results =
            typeof rawResults === 'string' ?
            JSON.parse(rawResults) :
            rawResults;

        var predictedSysIds = [];
        var seenSysIds = {};
        var resultKey;
        var predictionIndex;

        for (resultKey in results) {
            if (
                !results.hasOwnProperty(
                    resultKey
                )
            ) {
                continue;
            }

            var predictions =
                results[resultKey];

            if (
                !predictions ||
                typeof predictions.length ===
                'undefined'
            ) {
                continue;
            }

            for (
                predictionIndex = 0; predictionIndex <
                predictions.length; predictionIndex++
            ) {
                var prediction =
                    predictions[
                        predictionIndex
                    ];

                if (
                    prediction &&
                    prediction.predictedSysId
                ) {
                    var predictedSysId =
                        String(
                            prediction
                            .predictedSysId
                        );

                    if (
                        predictedSysId !==
                        incidentSysId &&
                        !seenSysIds[
                            predictedSysId
                        ]
                    ) {
                        seenSysIds[
                            predictedSysId
                        ] = true;

                        predictedSysIds.push(
                            predictedSysId
                        );
                    }
                }
            }
        }

        if (
            predictedSysIds.length === 0
        ) {
            gs.info(
                'SIMILARITY TEST: ' +
                'No similar incidents found.'
            );
        } else {
            var similarGR =
                new GlideRecord(
                    'incident'
                );

            similarGR.addQuery(
                'sys_id',
                'IN',
                predictedSysIds.join(',')
            );

            similarGR.query();

            /*gs.info(
                'SIMILARITY TEST: ' +
                'Unique similar incidents found = ' +
                predictedSysIds.length
            );*/

            while (similarGR.next()) {
				similarityIncidentsNumber.push(similarGR.getValue('number') + ' ');
				similarityIncidentsID.push(similarGR.getValue('sys_id') + ' ');
				similarityIncidentsResolutionCode.push(similarGR.getValue('close_notes') + ' ');
                /*gs.info(
                    'SIMILARITY TEST: ' +
                    similarGR.getValue(
                        'number'
                    ) +
                    ' | ' +
                    similarGR.getDisplayValue(
                        'state'
                    ) +
                    ' | ' +
                    similarGR.getValue(
                        'short_description'
                    ) +
                    ' | Close notes: ' +
                    (
                        similarGR.getValue(
                            'close_notes'
                        ) ||
                        'Not available'
                    )
                );*/


			}

			gs.info('Numbers ' + similarityIncidentsNumber.toString());
			gs.info('ID ' + similarityIncidentsID.toString());
			gs.info('Resolution Code ' + similarityIncidentsResolutionCode.toString());

        }
    } catch (exception) {
        gs.error(
            'SIMILARITY TEST ERROR: ' +
            (
                exception.message ||
                String(exception)
            )
        );
    }
}
